@startuml

class RepairShop {
  + Name : string
  + Address : string
  + NumberOfEmployees : int
  + CalculateAverageSeniority() : float
  + CalculateLongestRepair() : int
}

class Employee {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
  + YearsOfService : int
}

class Director extends Employee {
  + Age : int
}

class Repair {
  + Code : string
  + CheckInTime : datetime
  + CheckInDate : date
  + ReturnTime : time
  + ReturnDate : date
}

class Vehicle {
  + Model : string
  + Type : string
  + LicensePlate : string
  + YearOfRegistration : int
}

class Owner {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
}

class Manager {
  + PerformStaffAnalysis(RepairShop) : void
  + PerformRepairAnalysis(RepairShop) : void
}

class AccountingOffice {
  + ReceiveManagementResults() : void
}

RepairShop "1" *-- "1..*" Employee
RepairShop "1" -- "1" Director : manages
RepairShop "1" -- "0..*" Repair
Repair "1" -- "1" Vehicle
Vehicle "0..*" -- "1" Owner
Owner "1" -- "0..*" Vehicle
Manager "1" -- "0..*" RepairShop : analyzes
Director "1" -- "1" AccountingOffice : communicates results to

@enduml

